using System;
using UnityEngine;

namespace MPipeline
{
    /// <summary>
    /// Serialized geometry generated by MeshCombiner and consumed by the URP renderer feature.
    /// </summary>
    [CreateAssetMenu(menuName = "MPipeline/Cluster Geometry")]
    public sealed class ClusterGeometryAsset : ScriptableObject
    {
        public const int VerticesPerCluster = 384;
        public const int TrianglesPerCluster = 128;

        [SerializeField, HideInInspector]
        private Cluster[] clusters = Array.Empty<Cluster>();

        [SerializeField, HideInInspector]
        private Point[] points = Array.Empty<Point>();

        [SerializeField, HideInInspector]
        private int[] triangleMaterials = Array.Empty<int>();

        [SerializeField, HideInInspector]
        private Material[] sourceMaterials = Array.Empty<Material>();

        [SerializeField, HideInInspector]
        private MaterialData[] materialData = Array.Empty<MaterialData>();

        [SerializeField]
        private Texture2DArray baseMapArray;

        [SerializeField]
        private Bounds localBounds;

        public int ClusterCount => clusters == null ? 0 : clusters.Length;
        public int PointCount => points == null ? 0 : points.Length;
        public Bounds LocalBounds => localBounds;
        public Cluster[] Clusters => clusters;
        public Point[] Points => points;
        public int[] TriangleMaterials => triangleMaterials;
        public Material[] SourceMaterials => sourceMaterials;
        public MaterialData[] MaterialProperties => materialData;
        public Texture2DArray BaseMapArray => baseMapArray;

        public int MaterialCount => sourceMaterials == null ? 0 : sourceMaterials.Length;

        public void SetData(
            Cluster[] newClusters,
            Point[] newPoints,
            int[] newTriangleMaterials,
            Bounds bounds,
            Material[] newSourceMaterials = null,
            MaterialData[] newMaterialData = null,
            Texture2DArray newBaseMapArray = null)
        {
            clusters = newClusters ?? Array.Empty<Cluster>();
            points = newPoints ?? Array.Empty<Point>();
            triangleMaterials = newTriangleMaterials ?? Array.Empty<int>();
            sourceMaterials = newSourceMaterials ?? Array.Empty<Material>();
            materialData = newMaterialData ?? Array.Empty<MaterialData>();
            baseMapArray = newBaseMapArray;
            localBounds = bounds;
        }

        [Serializable]
        public struct MaterialData
        {
            public Vector4 color;
            public Vector4 uvScaleOffset;
            public int textureSlice;
            public int padding0;
            public int padding1;
            public int padding2;
        }

        private void OnValidate()
        {
            if (clusters == null)
                clusters = Array.Empty<Cluster>();
            if (points == null)
                points = Array.Empty<Point>();
            if (triangleMaterials == null)
                triangleMaterials = Array.Empty<int>();
            if (sourceMaterials == null)
                sourceMaterials = Array.Empty<Material>();
            if (materialData == null)
                materialData = Array.Empty<MaterialData>();
        }
    }
}
